<script>
(()=>{const el=document.getElementById('orderStatus');if(!el)return;async function check(){try{const r=await fetch(@json(route('orders.status',$order)),{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();el.textContent=d.status==='pending'&&d.approved?'Approved':d.status[0].toUpperCase()+d.status.slice(1);el.className='badge '+(d.status==='completed'?'bg-success':d.approved?'bg-info text-dark':'bg-warning text-dark');if(d.approved)document.getElementById('approvalBy').textContent=`Approved by ${d.approver??'Admin'} on ${d.approved_at??''}`;if(d.status==='completed'){document.querySelectorAll('form[action*="/complete"],form[action*="/approve"],form[action*="/cancel"]').forEach(f=>f.remove());}}catch(e){}}setInterval(check,5000)})();
</script>
